import {initialState,normalizeState,dayKey,previousDay,songBatch,dueCards,rateCard,learnLine,streak,toAnki,toSrt,parseLyrics,validateSegment,Rating,SubtitleCollection,recordStudy,studyHistory,librarySongs,switchSong,addSong,removeSong,songCardId,dailySongCount,dailyStatus,cardCategory,filterCards,practiceCard,undoRating} from './core.js';
import {lessons,sources} from './curriculum.js';
import {lessonQuestions,lessonSession,learnLessonItem,recordQuizAnswer,warmupItems,practiceSegment,videoSource} from './practice.js';
import {knowledge,knowledgeCategories,filterKnowledge,learnKnowledge} from './knowledge.js';
import {mistakeList} from './mistakes.js';
import {createStudyNote,updateStudyNote,removeStudyNote,studyNotes,noteSourceUrl} from './notebook.js';
import {ProgressSync} from './cloud.js';
const KEY='haru-korean-v1';let state=initialState();let storageWarning='';
try{const raw=localStorage.getItem(KEY);if(raw)state=normalizeState(JSON.parse(raw));}catch{storageWarning='旧进度读取失败，原数据未覆盖。可在学习设置中恢复有效备份；当前使用临时进度。';}
const el=(id)=>document.getElementById(id);const escape=(value)=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let historyDate='',historyLimit=60,libraryQuery='',libraryFilter='all',knowledgeCategory='all',knowledgeQuery='',knowledgeScope='all',reviewMode='due',cardQuery='',cardFilter='all',cardLimit=60,mistakesAll=false,lastRating=null;
const views=['today','course','song','review','settings','history','library','knowledge','notebook'];
const viewFromUrl=()=>views.includes(location.hash.slice(1))?location.hash.slice(1):'today';
let notebookQuery='',studyNoteId=null;
let view=viewFromUrl(),mini=state.minutes===3,session=null,reviewId=null,revealed=false,importPreview=null,toastTimer;
let player=null,playerReady=false,playerFailed=false,localUrl=null,loopOn=false,segmentActive=false,ticker=null,pendingSegment=false;
const audio=new Audio();audio.controls=true;audio.preload='metadata';audio.setAttribute('aria-label','本地歌曲播放器');
const collection=new SubtitleCollection({returnLastShown:true,returnNextToShow:true});
function rebuildTimeline(){collection.setSubtitles(state.song.lines.filter(x=>x.start!==null));}rebuildTimeline();
function toast(message){el('toast').textContent=message;el('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el('toast').classList.remove('show'),3500);}
const cloud=new ProgressSync({storage:localStorage,onRemote(next){lastRating=null;if(state.songId!==next.songId)resetSongPlayer();state=next;mini=state.minutes===3;reviewId=null;revealed=false;rebuildTimeline();render();},onStatus(text){if(el('syncIndicator'))el('syncIndicator').textContent=text;if(el('cloudStatus'))el('cloudStatus').textContent=text;if(cloud.conflict&&view==='settings')el('conflictActions').hidden=false;}});
function save(){try{if(storageWarning)return;cloud.changed(state);}catch{toast('浏览器无法保存进度，请及时导出备份。');}}
function download(name,data,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function today(){const k=dayKey();state.days[k]??={};const d=state.days[k];if(!('lessonId' in d))d.lessonId=lessons.findIndex((_,i)=>!state.completedLessons.includes(i));if(!d.reviewIds)d.reviewIds=dueCards(state).map(x=>x.id);return d;}
function dailyComplete(){
 const d=today();if(d.complete){toast('今天已经完成了，可以继续巩固或学习下一课。');return;}
 const status=dailyStatus(state,mini);
 if(!status.basic){toast('先完成今日基础小课。');return;}
 if(!status.review){toast(d.reviewIds.length?'还有今日到期复习，先回想一下。':'完成今日巩固练习后再打卡。');if(d.reviewIds.length){reviewMode='due';navigate('review');}else openPractice();return;}
 if(!status.song){if(status.useWarmup){toast(mini?'先完成一组跟读热身。':'先完成 4 组跟读热身。');openWarmup();}else{toast('今天的歌词还没学完，去歌曲工作台继续。');navigate('song');}return;}
 d.complete=true;d.mode=mini?'light':'regular';save();render();toast(mini?'今天的轻量任务完成了。明天继续。':'今天完成了，进步已经存下来。');
}
function syncSidebar(){el('sideSongTitle').textContent=state.songId?state.song.title:'还没有歌曲';el('sideSongArtist').textContent=state.song.artist||'添加一首喜欢的歌';el('dueBadge').textContent=dueCards(state).length;el('sideProgress').style.width=Math.round(state.completedLessons.length/lessons.length*100)+'%';el('sideCount').textContent=`基础小课 ${state.completedLessons.length} / ${lessons.length} · 歌曲 ${state.learned.length} 句`;document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.view===(view==='song'?'library':view)));el('viewLabel').textContent={today:'今日学习',song:'歌曲工作台',course:'基础小课',review:'我的复习',settings:'学习设置',history:'学习历史',library:'歌曲库',knowledge:'知识库',notebook:'学习笔记'}[view];}
function navigate(next){if(!views.includes(next))return;if(next!=='review')lastRating=null;if(el('lessonDialog').open)el('lessonDialog').close();if(next==='song'&&!state.songId)next='library';audio.pause();if(playerReady)player.pauseVideo();loopOn=false;segmentActive=false;clearInterval(ticker);ticker=null;if(view==='song')disposeVideo();view=next;if(location.hash!=='#'+next)history.pushState(null,'','#'+next);reviewId=null;revealed=false;render();window.scrollTo({top:0,behavior:'smooth'});}
function render(){if(view==='song'&&!state.songId){view='library';history.replaceState(null,'','#library');}if(view==='song')disposeVideo();syncSidebar();el('content').classList.toggle('minimode',mini);el('content').innerHTML=({today:renderToday,song:renderSong,course:renderCourse,review:renderReview,settings:renderSettings,history:renderHistory,library:renderLibrary,knowledge:renderKnowledge,notebook:renderNotebook}[view])();bind();save();if(view==='song'&&state.songId)mountSong();}
function progressWeek(){let end=dayKey(),keys=[];for(let i=0;i<7;i++){keys.unshift(end);end=previousDay(end);}return keys.map(k=>`<div class="day ${state.days[k]?.complete?'done':''} ${k===dayKey()?'today':''}"><span>${new Date(k+'T12:00:00+08:00').toLocaleDateString('zh-CN',{weekday:'short',timeZone:'Asia/Shanghai'})}</span><div>${state.days[k]?.complete?'✓':k.slice(-2)}</div></div>`).join('');}
function task(number,title,desc,label,action,done=false){return `<div class="task"><div class="task-number">${done?'✓':number}</div><div class="task-details"><h3>${title}</h3><p>${desc}</p></div><button data-action="${action}">${done?'再练一次':label}</button></div>`;}
function renderToday(){const d=today(),lesson=lessons[d.lessonId],batch=songBatch(state),learnedToday=batch.filter(x=>state.learned.includes(x.id)).length;const totalDays=Object.values(state.days).filter(x=>x.complete).length,status=dailyStatus(state,mini);
 return `<div class="welcome"><div><div class="eyebrow">하루 · A LITTLE EVERY DAY</div><h1>${d.complete?'今天，又向前了一点。':'从今天的一点点开始。'}</h1><p>不用一下学会韩语。每天学一点，再在喜欢的歌里用出来。</p></div><button class="pill" data-action="settings">每天 ${mini?'3':Math.max(15,state.minutes)} 分钟　⌄</button></div>${storageWarning?`<div class="gentle">${escape(storageWarning)}</div>`:''}<section class="hero"><div class="hero-text"><div class="eyebrow">YOUR DAILY MIX · 基础 + 复习 + 歌曲</div><h2>学一点韩语，<br>离喜欢的歌近一点。</h2><p>${mini?'今天只做最小一步：认识一个知识点，再练一句或一组跟读。':`今日小课：${lesson?lesson.title:'基础阶段已完成，继续复习与系统课程'}。<br>${state.song.lines.length?`《${escape(state.song.title)}》每天 ${state.quota} 句。`:'今天还有 4 组跟读热身，打开就能练。'}`}</p><div class="hero-actions"><button class="primary" data-action="dailyLesson">${(mini?(d.basic||d.lightBasic):d.basic)?'继续巩固':'开始今天的小课'} <span>↗</span></button><button class="text-button" data-action="mini">${mini?'恢复完整学习 →':'今天有点忙，只学 3 分钟 →'}</button></div></div><div class="hero-art" aria-hidden="true"><div class="orb"></div><div class="vinyl"><div class="record-label">${escape(state.song.artist.slice(0,12))}<b>${escape(state.song.title.slice(0,20))}</b><i></i></div></div><div class="art-note">ONE LINE AT A TIME.</div></div></section><div class="stats"><div class="stat"><div class="stat-icon">◷</div><div><strong>${totalDays}</strong><small>天</small><p>累计完成学习</p></div></div><div class="stat"><div class="stat-icon">♫</div><div><strong>${librarySongs(state).reduce((n,x)=>n+x.learned.length,0)}</strong><small>句</small><p>已经学过的歌词</p></div></div><div class="stat"><div class="stat-icon">↺</div><div><strong>${dueCards(state).length}</strong><small>张</small><p>到期复习卡片</p></div></div></div><div class="columns"><section><div class="section-head"><h2>今天，做好这三件事</h2><small>${mini?'轻量模式':'约 '+Math.max(15,state.minutes)+' 分钟'}</small></div><div class="panel">${task('01',lesson?lesson.title:'基础回顾',mini?'学一个知识点 · 约 1 分钟':'4 个知识点 + 8 道识读与听辨练习 · 约 7 分钟','开始','dailyLesson',status.basic)}${task('02','复习容易忘的内容',d.reviewIds.length?`${d.reviewIds.length} 张今日到期卡 · 约 3 分钟`:mini?'轻量模式可跳过巩固题，先练知识点和跟读':'没有到期旧卡，来做 8 道今日巩固题',d.reviewIds.length?'复习':'开始巩固',d.reviewIds.length?'review':'dailyPractice',status.review)}${task('03',status.useWarmup?'跟读热身':!batch.length?'歌曲练习':`《${escape(state.song.title)}》`,status.useWarmup?mini?'练 1 组发音与回忆 · 不用准备素材':'练 4 组发音与回忆 · 不用准备素材':!batch.length?'今日新句额度已完成，可回听或巩固':`今日 ${learnedToday} / ${batch.length} 句 · 听、读、理解，再跟唱`,'开始练习',status.useWarmup?'warmup':'song',status.song)}</div><div class="control-row"><button class="primary" data-action="completeDay">${d.complete?'今日已完成 ✓':'完成今天的学习 ✓'}</button>${d.basic?'<button class="secondary" data-action="nextLesson">继续下一课 →</button>':''}</div></section><section><div class="section-head"><h2>积累，比完美更重要</h2><small>连续 ${streak(state)} 天</small></div><div class="panel"><h3>最近 7 天</h3><div class="week">${progressWeek()}</div><div class="gentle">${streak(state)?'你已经在积累了。今天学会的，明天再见一次。':'从第一天开始就好。漏学后回来，继续下一小步。'}</div><p class="helper">这里的完成天数来自实际任务。普通学习和轻量学习都会留下记录。</p></div></section></div><section class="roadmap"><div class="section-head"><h2>你的韩语起步路线</h2><div><button class="text-button" data-action="knowledge">打开知识库 →</button><button class="text-button" data-action="course">查看全部课程 →</button></div></div><div class="steps">${[['01','字母与拼读','元音、辅音、音节组合'],['02','发音与听辨','收音、连音、音变'],['03','词汇与句型','问候、介绍、基本语序'],['04','每天用一点','歌词实践 + 记忆复习']].map((x,i)=>`<div class="step ${Math.min(3,Math.floor(state.completedLessons.length/4))===i?'active':''}"><small>STAGE ${x[0]}</small><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div></section>`;}
function knowledgeResults(){const entries=filterKnowledge(knowledgeCategory,knowledgeQuery,knowledgeScope,state.cards);return entries.length?entries.map(x=>`<article class="panel knowledge-entry"><div class="eyebrow">${knowledgeCategories[x.category]} · ${escape(x.topic)}</div><h2>${escape(x.title)}</h2><p class="knowledge-meaning">${escape(x.meaning)}</p><p class="muted knowledge-summary">${escape(x.explanation)}</p><div class="control-row"><button class="secondary" data-knowledge="${x.id}" aria-label="查看 ${escape(x.title)}">查看详解 →</button>${state.cards['knowledge:'+x.id]?'<span class="helper">已加入复习 ✓</span>':''}</div></article>`).join(''):'<section class="panel empty knowledge-empty"><h2>没有找到匹配的内容</h2><p class="muted">试试其他中文、韩文关键词，或切换到「全部知识」。</p><button class="secondary" data-knowledge-reset>清除筛选</button></section>';}
function renderKnowledge(){return `<div class="welcome"><div><div class="eyebrow">KNOWLEDGE · 随时查，随时学</div><h1>把零散知识，慢慢串起来。</h1><p>发音、语法、词汇与日常语句。每条都有解释和例子，随时查阅，也可以加入复习。</p></div><span class="pill">入门知识 ${knowledge.length} 条</span></div><div class="knowledge-categories" role="group" aria-label="知识分类">${[['all','全部知识'],...Object.entries(knowledgeCategories)].map(([id,label])=>`<button class="knowledge-category ${knowledgeCategory===id?'selected':''}" aria-pressed="${knowledgeCategory===id}" data-knowledge-category="${id}"><strong>${label}</strong><span>${id==='all'?knowledge.length:knowledge.filter(x=>x.category===id).length} 条</span></button>`).join('')}</div><div class="library-toolbar knowledge-toolbar"><label class="field-label knowledge-search">搜索知识<input type="search" id="knowledgeSearch" value="${escape(knowledgeQuery)}" placeholder="搜索中文或韩文，例如：喜欢、은、咖啡"></label><label class="field-label">学习状态<select id="knowledgeScope">${[['all','全部内容'],['saved','已加入复习'],['new','尚未加入复习']].map(([id,label])=>`<option value="${id}" ${knowledgeScope===id?'selected':''}>${label}</option>`).join('')}</select></label></div><div class="section-head"><h2>${knowledgeCategory==='all'?'全部知识':knowledgeCategories[knowledgeCategory]}</h2><span class="helper" id="knowledgeCount" role="status">找到 ${filterKnowledge(knowledgeCategory,knowledgeQuery,knowledgeScope,state.cards).length} 条</span></div><div class="knowledge-grid" id="knowledgeResults">${knowledgeResults()}</div><div class="resources"><p>中文说明与练习例句为本项目整理的入门内容。浏览不影响每日任务；主动加入复习后，会自动保存到你的学习历史。</p><p>继续查词与系统学习：${sources.map(([name,url])=>`<a href="${url}" target="_blank" rel="noopener">${name} ↗</a>`).join('')}</p></div>`;}
function bindKnowledge(root){
 root.querySelectorAll('[data-knowledge]').forEach(button=>button.onclick=()=>openKnowledge(button.dataset.knowledge));
 root.querySelectorAll('[data-knowledge-category]').forEach(button=>button.onclick=()=>{knowledgeCategory=button.dataset.knowledgeCategory;render();});
 root.querySelectorAll('[data-knowledge-reset]').forEach(button=>button.onclick=()=>{knowledgeCategory='all';knowledgeQuery='';knowledgeScope='all';render();});
 if(root===document&&el('knowledgeScope'))el('knowledgeScope').onchange=event=>{knowledgeScope=event.target.value;render();};
 if(root===document&&el('knowledgeSearch'))el('knowledgeSearch').oninput=event=>{knowledgeQuery=event.target.value;el('knowledgeResults').innerHTML=knowledgeResults();el('knowledgeCount').textContent='找到 '+filterKnowledge(knowledgeCategory,knowledgeQuery,knowledgeScope,state.cards).length+' 条';bindKnowledge(el('knowledgeResults'));};
}
function notebookList(){const notes=studyNotes(state,notebookQuery);return notes.length?notes.map(note=>`<button class="notebook-item ${note.id===studyNoteId?'selected':''}" aria-pressed="${note.id===studyNoteId}" data-study-note="${escape(note.id)}"><strong>${escape(note.title)}</strong><span>${escape(note.body.slice(0,85)||'还没有正文，点击开始记录。')}</span><small>${escape(new Date(note.updatedAt).toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai'}))}</small></button>`).join(''):'<p class="muted">'+(notebookQuery?'没有匹配的笔记，试试其他关键词。':'还没有笔记，点击「新建笔记」开始。')+'</p>';}
function noteSourceLink(source){const href=noteSourceUrl(source);return href?`<a class="text-button" href="${escape(href)}" target="_blank" rel="noopener noreferrer">打开视频 / 来源 ↗</a>`:'';}
function renderNotebook(){
 const all=studyNotes(state);if(!all.some(note=>note.id===studyNoteId))studyNoteId=all[0]?.id||null;const note=all.find(x=>x.id===studyNoteId);
 return `<div class="welcome"><div><div class="eyebrow">MY NOTEBOOK · 边看边记</div><h1>把视频里的收获，记在这里。</h1><p>一节课一篇笔记。记录发音、语法、生词和时间点，修改后自动保存。</p></div><button class="primary" id="newStudyNote">＋ 新建笔记</button></div>${storageWarning?`<p class="gentle">${escape(storageWarning)}</p>`:''}<div class="notebook-layout"><section class="panel notebook-index"><label class="field-label">搜索笔记<input type="search" id="notebookSearch" value="${escape(notebookQuery)}" placeholder="搜索标题、正文或课程出处"></label><p class="helper" id="notebookCount" role="status">${studyNotes(state,notebookQuery).length} / ${all.length} 篇笔记</p><div id="notebookList">${notebookList()}</div></section>${note?`<section class="panel notebook-editor"><div class="section-head"><h2>正在记录</h2><button class="text-button" id="deleteStudyNote">删除这篇笔记</button></div><label class="field-label">笔记标题<input id="studyNoteTitle" maxlength="120" value="${escape(note.title)}" placeholder="例如：第一讲 · 单元音与辅音 ㅇ"></label><label class="field-label">视频链接 / 课程出处（选填）<input id="studyNoteSource" maxlength="2000" value="${escape(note.source)}" placeholder="粘贴视频链接，或填写课程名称和集数"></label><div id="noteSourceLink">${noteSourceLink(note.source)}</div><label class="field-label">笔记正文<textarea id="studyNoteBody" class="notes" maxlength="30000" placeholder="课程要点：&#10;&#10;生词 / 例句：&#10;&#10;视频时间点 / 还不懂的地方：">${escape(note.body)}</textarea></label><div class="notebook-meta"><span id="studyNoteUpdated">${escape('最近修改：'+new Date(note.updatedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}))}</span><span id="studyNoteLength">${note.body.length} / 30000 字</span></div><p class="helper">输入时自动保存，云端状态见页面右上角。笔记也会包含在完整进度备份中。</p><p id="studyNoteError" role="status"></p></section>`:'<section class="panel empty"><div class="hangul-preview">기록</div><h2>从今天这节视频课开始。</h2><p class="muted">新建笔记后，可以直接粘贴课堂要点，随时回来继续写。</p></section>'}</div>`;
}
function bindNotebook(root){
 root.querySelectorAll('[data-study-note]').forEach(button=>button.onclick=()=>{studyNoteId=button.dataset.studyNote;render();});
 if(root!==document||!el('newStudyNote'))return;
 const refresh=()=>{el('notebookList').innerHTML=notebookList();el('notebookCount').textContent=`${studyNotes(state,notebookQuery).length} / ${state.studyNotes.length} 篇笔记`;bindNotebook(el('notebookList'));};
 el('notebookSearch').oninput=event=>{notebookQuery=event.target.value;refresh();};
 el('newStudyNote').onclick=()=>{try{studyNoteId=createStudyNote(state).id;notebookQuery='';save();render();el('studyNoteTitle').focus();el('studyNoteTitle').select();}catch(error){toast(error.message);}};
 if(!el('studyNoteBody'))return;
 const update=()=>{try{const note=updateStudyNote(state,studyNoteId,{title:el('studyNoteTitle').value,source:el('studyNoteSource').value,body:el('studyNoteBody').value});save();el('studyNoteUpdated').textContent='最近修改：'+new Date(note.updatedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'});el('studyNoteLength').textContent=note.body.length+' / 30000 字';el('noteSourceLink').innerHTML=noteSourceLink(note.source);el('studyNoteError').textContent='';refresh();}catch(error){el('studyNoteError').textContent=error.message;}};
 for(const id of ['studyNoteTitle','studyNoteSource','studyNoteBody'])el(id).oninput=update;
 el('deleteStudyNote').onclick=()=>{const id=studyNoteId,note=state.studyNotes.find(x=>x.id===id);showDialog('删除学习笔记',`<h2>删除《${escape(note.title)}》？</h2><p>这篇笔记会从已同步的设备移除。确认前可以取消，其他笔记和学习进度会保留。</p><div class="control-row"><button class="secondary" id="cancelNoteDelete">取消</button><button class="primary" id="confirmNoteDelete">确认删除这篇笔记</button></div>`);el('cancelNoteDelete').onclick=()=>el('lessonDialog').close();el('confirmNoteDelete').onclick=()=>{removeStudyNote(state,id);save();el('lessonDialog').close();render();toast('这篇笔记已删除。');};};
}
function openKnowledge(id){
 const entry=knowledge.find(x=>x.id===id);if(!entry)return;
 const saved=!!state.cards['knowledge:'+id],related=(entry.related||[]).map(id=>knowledge.find(x=>x.id===id)).filter(Boolean);
 showDialog('知识库 · '+knowledgeCategories[entry.category]+' · '+entry.topic,`<h2>${escape(entry.title)}</h2><p class="knowledge-definition">${escape(entry.meaning)}</p><p class="lesson-desc">${escape(entry.explanation)}</p><div class="control-row"><button class="secondary" id="knowledgeSpeak">▶ 听示范</button><button class="primary" id="knowledgeLearn" ${saved?'disabled':''}>${saved?'已加入复习 ✓':'学过了，加入复习'}</button></div><h3>例子与用法</h3>${entry.examples.map(example=>`<div class="knowledge-example"><p class="lyric-text">${escape(example.ko)}</p><p>${escape(example.zh)}</p>${example.parts?`<p class="muted">${escape(example.parts)}</p>`:''}<button class="text-button" data-speak="${escape(example.ko)}">▶ 听这句</button></div>`).join('')}${related.length?`<h3>相关语法</h3><div class="control-row">${related.map(x=>`<button class="secondary" data-knowledge="${x.id}">${escape(x.title)} →</button>`).join('')}</div>`:''}${entry.lessonId!==undefined?`<div class="control-row"><button class="secondary" id="knowledgeLesson">练习相关小课：${escape(lessons[entry.lessonId].title)} →</button></div>`:''}<p class="helper">朗读使用设备的韩语语音；可到基础韩语词典听真人发音。加入复习后通常从明天开始安排。</p>`);
 el('knowledgeSpeak').onclick=()=>speak(entry.audio);el('knowledgeLearn').onclick=()=>{learnKnowledge(state,id);save();render();openKnowledge(id);toast('已加入复习，知识和例句已保存到学习历史。');};
 el('lessonBody').querySelectorAll('[data-speak]').forEach(button=>button.onclick=()=>speak(button.dataset.speak));bindKnowledge(el('lessonBody'));
 if(el('knowledgeLesson'))el('knowledgeLesson').onclick=()=>openLesson(entry.lessonId);
}
function renderCourse(){return `<div class="welcome"><div><div class="eyebrow">FOUNDATIONS · 韩语是主线</div><h1>从字母，到说出第一句。</h1><p>14 节起步小课。一次一点，完成练习后自动加入复习。</p></div><span class="pill">${state.completedLessons.length} / ${lessons.length} 完成</span></div><div class="course-grid">${lessons.map((l,i)=>`<article class="course-card"><div class="eyebrow">LESSON ${String(i+1).padStart(2,'0')} ${state.completedLessons.includes(i)?'· ✓ 已学':''}</div><h3 style="margin-top:9px">${l.title}</h3><div class="hangul-preview">${l.preview}</div><p>${l.goal}</p><button class="primary" data-lesson="${i}">${state.completedLessons.includes(i)?'巩固知识':'开始学习'}　↗</button></article>`).join('')}</div><div class="resources">这是基础起步阶段。完成后可用世宗学堂课程继续系统学习；本页不等同于完整初级韩语课程。<p>${sources.map(([n,u])=>`<a href="${u}" target="_blank" rel="noopener">${n} ↗</a>`).join('')}</p></div>`;}
function renderSong(){const batch=songBatch(state),segment=practiceSegment(batch)||state.segment,source=videoSource(state.song);return `<div class="song-top"><div><div class="eyebrow">SONG PRACTICE · 每天 ${state.quota} 句</div><h1>${escape(state.song.title)}</h1><p class="muted">${escape(state.song.artist)} · 听懂一点，唱好一点。</p></div><div class="control-row"><button class="pill" data-action="library">歌曲库 / 切换</button><button class="pill" data-action="import">导入 / 更换歌词 ＋</button></div></div><div class="song-layout"><section><details class="media-options"><summary>更换视频来源（可选）</summary><div class="control-row"><label class="helper">MV 播放来源 <select id="mvSource" style="width:auto;margin:0"><option value="bilibili" ${source!=='youtube'?'selected':''}>Bilibili</option><option value="youtube" ${source==='youtube'?'selected':''}>YouTube（备用）</option></select></label></div></details><div class="video-wrap" id="videoWrap"><div class="video-placeholder"><div class="big-note">♫</div><strong>跟着 MV 练习</strong><p>正在准备已保存的视频来源。无需每次选择。</p><button class="secondary" id="loadVideo">加载 MV</button></div></div><a class="text-button" id="openMv" ${source==='youtube'?!state.song.videoId?'hidden':'':!state.song.biliBvid?'hidden':''} href="${source==='youtube'?'https://www.youtube.com/watch?v='+escape(state.song.videoId):'https://www.bilibili.com/video/'+escape(state.song.biliBvid)+'/'}" target="_blank" rel="noopener">在来源网站打开 MV ↗</a><details class="panel media-options" style="margin-top:18px"><summary>本地音频与手动片段（可选）</summary><p class="helper">有时间轴的歌词会自动选好片段；也可以在这里手动微调。</p><label class="audio-import" for="audioFile"><strong>＋ ${localUrl?'更换本地歌曲音频':'选择本地歌曲音频'}</strong><p id="audioName">音频只在当前浏览器播放；本地播放器支持细致变速。</p></label><input hidden type="file" id="audioFile" accept="audio/*,video/mp4"><div id="audioHost"></div><div class="panel"><div class="section-head"><h3>只练一个片段</h3><span class="helper">A–B 循环</span></div><div class="control-grid"><label>A 起点（秒）<input id="startTime" type="number" min="0" step="0.1" value="${segment.start}"></label><label>B 终点（秒）<input id="endTime" type="number" min="0.1" step="0.1" value="${segment.end}"></label></div><div class="control-row"><button class="secondary" id="setStart">当前设为 A</button><button class="secondary" id="setEnd">当前设为 B</button><label class="helper">速度 <select id="rate" style="width:auto;margin:0">${[0.5,0.65,0.75,0.8,1].map(x=>`<option value="${x}" ${state.segment.rate===x?'selected':''}>${x}×</option>`).join('')}</select></label></div><div class="control-row"><button class="primary" id="playSegment">播放片段 ▶</button><button class="secondary" id="loopToggle" aria-pressed="false">循环：关闭</button><button class="text-button" id="stopPlayback">暂停</button></div><div id="liveSubtitle" class="live-subtitle" aria-live="off">${state.song.lines.some(x=>x.start!==null)?'导入的时间轴会在这里显示当前句。':'没有时间轴时，可先练右侧的发音热身；手动选段是可选功能。'}</div><p id="playerStatus" class="helper">Bilibili 支持跳转到句子起点；精确停止、循环与变速支持 YouTube 和本地音频。</p></div></details></section><section><div class="panel practice-intro"><h2>今天的练习已安排好</h2><p>${batch.length?`从第 ${batch[0].index+1} 句开始，按顺序练 ${batch.length} 句。${practiceSegment(batch)?'片段已按歌词时间轴选好。':'先逐句跟读，原唱可以在左侧播放。'}`:'先做 4 组跟读热身，再听喜欢的 MV。无需导入文件或填写秒数。'}</p><div class="control-row">${batch.length&&practiceSegment(batch)?'<button class="primary" id="playDaily">▶ 播放今日片段</button>':''}<button class="${batch.length?'secondary':'primary'}" data-action="warmup">${today().warmup?'再练一次发音热身':'开始发音热身 →'}</button></div><p class="helper">热身来自基础课程，不是歌曲原文。</p></div><div class="section-head"><h2>今天的新句</h2><span class="helper" id="songBatchCount">${batch.filter(x=>state.learned.includes(x.id)).length} / ${batch.length}</span></div>${batch.length?batch.map(line=>renderLine(line,true)).join(''):`<div class="panel empty"><div class="hangul-preview">하루</div><h3>${state.song.lines.length?state.learned.length>=state.song.lines.length?'新句都学过了':'今天的新句额度已用完':'还没有这首歌的歌词'}</h3><p class="muted">${state.song.lines.length?'所有歌曲共用每天的新句额度。今天先巩固，明天继续。':'现在可以直接跟读热身、观看 MV。以后添加歌词即可自动安排每日新句；带时间轴的 LRC / SRT 还能自动选片段。'}</p><button class="primary" data-action="${state.song.lines.length?'review':'warmup'}">${state.song.lines.length?'去复习':'直接开始跟读'}</button></div>`}<div class="gentle" style="margin-top:16px">练一句的顺序：听 2 遍 → 分音节读 → 理解意思 → 跟唱 3 遍。能慢速读清楚，也是在进步。</div>${state.song.lines.length?`<details class="panel" id="allLines" style="margin-top:20px"><summary>全部 ${state.song.lines.length} 句 · 已学 ${state.learned.length} 句</summary><div>${state.song.lines.map(line=>`<div class="segment"><small>${line.index+1}</small><div><span>${escape(line.text)}</span><br><small data-line-progress="${line.id}">${state.learned.includes(line.id)?'✓ 已学':batch.some(x=>x.id===line.id)?'今日学习':'以后慢慢学'}</small></div>${line.start!==null?`<button data-segment="${line.id}">听片段</button>`:''}</div>`).join('')}</div></details>`:''}</section></div>`;}
function updateSongLearning(){
 const batch=songBatch(state);syncSidebar();
 if(el('songBatchCount'))el('songBatchCount').textContent=batch.filter(x=>state.learned.includes(x.id)).length+' / '+batch.length;
 document.querySelectorAll('[data-learn]').forEach(button=>{if(state.learned.includes(button.dataset.learn)){button.disabled=true;button.textContent='已加入复习 ✓';const status=button.closest('[data-lyric-card]')?.querySelector('[data-line-status]');if(status)status.textContent='✓ 已学';}});
 document.querySelectorAll('[data-line-progress]').forEach(label=>{if(state.learned.includes(label.dataset.lineProgress))label.textContent='✓ 已学';});
 const summary=el('allLines')?.querySelector('summary');if(summary)summary.textContent=`全部 ${state.song.lines.length} 句 · 已学 ${state.learned.length} 句`;
}
function renderLine(line,isToday){return `<article class="panel lyric-card" data-lyric-card="${line.id}" style="margin-bottom:14px"><div class="section-head"><span class="eyebrow">LINE ${String(line.index+1).padStart(2,'0')}</span><span class="helper" data-line-status>${state.learned.includes(line.id)?'✓ 已学':line.start!==null?`${(line.start/1000).toFixed(1)}–${(line.end/1000).toFixed(1)} 秒`:'逐句练习'}</span></div><p class="lyric-text">${escape(line.text)}</p><div class="control-row">${line.start!==null?`<button class="secondary" data-segment="${line.id}">▶ 听这一句</button>`:''}<button class="text-button" data-speak="${escape(line.text)}">听朗读</button><a class="text-button" href="https://krdict.korean.go.kr/chn/mainAction?nation=chn" target="_blank" rel="noopener">查词 ↗</a></div><label class="helper">我的释义 / 生词 / 发音笔记<textarea class="notes" data-note="${line.id}" placeholder="写下你理解的意思，或记一个需要复习的词……">${escape(state.notes[line.id]||'')}</textarea></label><p class="helper">朗读使用浏览器韩语语音，跟唱以原唱音频为准。</p>${isToday?`<button class="primary" data-learn="${line.id}" ${state.learned.includes(line.id)?'disabled':''}>${state.learned.includes(line.id)?'已加入复习 ✓':'今天练过了，加入复习 ✓'}</button>`:''}</article>`;}
const cardLabels={basic:'基础学习',song:'歌曲练习',knowledge:'知识库'};
function reviewSwitcher(due){return `${lastRating?'<div class="gentle undo-rating" role="status"><span>刚才评分点错了？可撤销本次页面里的最后一次评分。</span><button class="secondary" data-action="undoRating">撤销上次评分</button></div>':''}<div class="review-tabs" role="group" aria-label="复习范围"><button class="${reviewMode==='due'?'selected':''}" aria-pressed="${reviewMode==='due'}" data-action="dueCards">今日到期 · ${due}</button><button class="${reviewMode==='all'?'selected':''}" aria-pressed="${reviewMode==='all'}" data-action="allCards">全部卡片 · ${Object.keys(state.cards).length}</button><button class="${reviewMode==='mistakes'?'selected':''}" aria-pressed="${reviewMode==='mistakes'}" data-action="mistakes">错题巩固 · <span id="mistakeCount">${mistakeList(state).length}</span></button></div>`;}
function cardLibraryResults(){const cards=filterCards(state,cardQuery,cardFilter),now=Date.now();return cards.length?cards.slice(0,cardLimit).map(card=>`<article class="panel saved-card"><div class="section-head"><span class="eyebrow">${cardLabels[cardCategory(card)]}</span><span class="pill">${new Date(card.fsrs.due)<=now?'已到期':'未到期'}</span></div><h2>${escape(card.front)}</h2><p class="helper">下次复习：${escape(new Date(card.fsrs.due).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}))}</p><button class="secondary" data-practice-card="${escape(card.id)}" aria-label="自测 ${escape(card.front)}">回想一下，再看答案 →</button></article>`).join(''):'<section class="panel empty knowledge-empty"><h2>这里还没有匹配的卡片</h2><p class="muted">试试其他关键词或分类。完成基础知识点，或在知识库点「加入复习」，卡片就会出现在这里。</p></section>';}
function renderCardLibrary(){const count=filterCards(state,cardQuery,cardFilter).length;return `${reviewSwitcher(dueCards(state).length)}<div class="welcome"><div><div class="eyebrow">MY CARDS · 学过的，随时回看</div><h1>把学过的内容，再想一遍。</h1><p>基础、歌曲与知识库卡片集中在这里。提前自测会留下历史记录，到期时间按原计划安排。</p></div></div><div class="library-toolbar"><label class="field-label">查找卡片<input type="search" id="cardSearch" value="${escape(cardQuery)}" placeholder="搜索韩文、中文或笔记"></label><label class="field-label">卡片来源<select id="cardFilter">${[['all','全部来源'],...Object.entries(cardLabels)].map(([id,label])=>`<option value="${id}" ${cardFilter===id?'selected':''}>${label}</option>`).join('')}</select></label></div><div class="section-head"><h2>我的卡片</h2><span class="helper" id="cardCount" role="status">找到 ${count} 张</span></div><div class="knowledge-grid" id="cardResults">${cardLibraryResults()}</div><div class="control-row"><button class="secondary" id="moreCards" data-action="moreCards" ${count<=cardLimit?'hidden':''}>查看更多卡片</button><button class="text-button" data-action="anki">导出 Anki 卡片 →</button></div>`;}
function refreshCards(){const cards=filterCards(state,cardQuery,cardFilter);el('cardResults').innerHTML=cardLibraryResults();el('cardCount').textContent='找到 '+cards.length+' 张';el('moreCards').hidden=cards.length<=cardLimit;bindCards(el('cardResults'));}
function bindCards(root){root.querySelectorAll('[data-practice-card]').forEach(button=>button.onclick=()=>openCardPractice(button.dataset.practiceCard));if(root===document&&el('cardSearch')){el('cardSearch').oninput=event=>{cardQuery=event.target.value;cardLimit=60;refreshCards();};el('cardFilter').onchange=event=>{cardFilter=event.target.value;cardLimit=60;refreshCards();};}}
function openCardPractice(id){
 const card=state.cards[id];if(!card)return;let answer=false;
 const show=()=>{showDialog('自由自测 · '+cardLabels[cardCategory({...card,id})],`<h2>先回想，再核对。</h2><p class="lyric-text">${escape(card.front)}</p>${/[가-힣]/.test(card.front)?'<button class="secondary" id="cardSpeak">▶ 听韩语朗读</button>':''}${answer?`<div class="card-answer">${escape(card.back)}</div><button class="primary" id="recordSelfTest">练过了，记录这次自测 ✓</button>`:'<p class="muted">回想意思、发音或用法，试着独立说出来。</p><button class="primary" id="selfTestAnswer">显示答案</button>'}<p class="helper">自由自测不计入到期任务；正式复习请在「今日到期」中按记忆程度评分。</p>`);
 if(el('cardSpeak'))el('cardSpeak').onclick=()=>speak(card.front);if(el('selfTestAnswer'))el('selfTestAnswer').onclick=()=>{answer=true;show();};if(el('recordSelfTest'))el('recordSelfTest').onclick=()=>{practiceCard(state,id);save();el('lessonDialog').close();toast('这次自测已记入历史，复习时间保持原计划。');};};show();
}
function renderMistakes(){const entries=mistakeList(state,mistakesAll),pending=mistakeList(state).length;return `${reviewSwitcher(dueCards(state).length)}<div class="welcome"><div><div class="eyebrow">MISTAKES · 把没懂的再弄懂</div><h1>答错的地方，值得再练一次。</h1><p>小课和巩固题答错后自动收集。在这里答对，会标记为已巩固，题目与解释仍可回看。</p></div></div><div class="section-head"><h2>${pending} 道待巩固</h2><button class="primary" data-action="practiceMistakes" ${pending?'':'disabled'}>集中练习 →</button></div><label class="mistake-filter"><input type="checkbox" id="mistakesAll" ${mistakesAll?'checked':''}> 同时查看已巩固的题目</label><div class="knowledge-grid">${entries.length?entries.map(entry=>`<article class="panel mistake-entry"><div class="section-head"><span class="eyebrow">${escape(lessons[entry.lessonId].title)}</span><span class="pill">${entry.resolvedAt?'已巩固 ✓':'待巩固'}</span></div><h2>${escape(entry.question[0])}</h2><p class="helper">答错 ${entry.count} 次 · 最近 ${escape(new Date(entry.lastWrongAt).toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai'}))}</p><p class="muted">上次选择：${escape(entry.wrongAnswer)}</p><button class="secondary" data-mistake="${entry.id}">重新做这道题 →</button></article>`).join(''):`<section class="panel empty knowledge-empty"><h2>${mistakesAll?'还没有错题记录':'目前没有待巩固的错题'}</h2><p class="muted">${mistakesAll?'学习中答错的题会自动出现在这里。':'可以勾选上方选项回看已巩固的题目，或继续今天的小课。'}</p><button class="secondary" data-action="dailyLesson">继续基础学习 →</button></section>`}</div>`;}
function openMistakePractice(ids){const entries=ids.map(id=>state.mistakes[id]).filter(Boolean);if(!entries.length){toast('目前没有待巩固的错题。');return;}session={id:entries[0].lessonId,index:0,quiz:0,phase:'quiz',light:false,mistakeKeys:entries.map(x=>x.lessonId+':'+x.questionIndex),questions:entries.map(x=>structuredClone(x.question))};showLesson();}
function renderReview(){if(reviewMode==='mistakes')return renderMistakes();if(reviewMode==='all')return renderCardLibrary();const due=dueCards(state),switcher=reviewSwitcher(due.length);if(!reviewId||!state.cards[reviewId])reviewId=due[0]?.id;const c=state.cards[reviewId];if(!c)return `${switcher}<div class="welcome"><div><div class="eyebrow">REVIEW · 让记忆留下来</div><h1>今天，没有到期的卡片。</h1><p>学完小课和歌词后，会自动生成复习卡。明天再来见它们。</p></div></div><div class="panel empty"><div class="hangul-preview">기억</div><h2>慢慢记住，就很好。</h2><p class="muted">${Object.keys(state.cards).length?`目前有 ${Object.keys(state.cards).length} 张卡片，可随时查看和提前自测。`:'先学习知识点或在知识库加入内容，系统会自动生成卡片。'}</p><button class="primary" data-action="${Object.keys(state.cards).length?'allCards':'knowledge'}">${Object.keys(state.cards).length?'查看全部卡片':'去知识库开始'}</button><div class="control-row" style="justify-content:center"><button class="text-button" data-action="anki">导出给 Anki</button></div></div>`;
 return `${switcher}<div class="welcome"><div><div class="eyebrow">SPACED REPETITION · FSRS</div><h1>再见一次，就记牢一点。</h1><p>先回想，再看答案。按真实记忆程度选择，系统会安排下次复习。</p></div><span class="pill">${due.length} 张到期</span></div><article class="panel review-card"><div class="eyebrow">${c.id.startsWith('knowledge:')?'知识库':c.kind==='song'?'歌曲练习':'基础学习'}</div><div class="review-character ${c.front.length>12?'long':''}">${escape(c.front)}</div>${revealed?`<p style="white-space:pre-wrap">${escape(c.back)}</p><div class="rating"><button class="secondary" data-rating="${Rating.Again}">忘记了</button><button class="secondary" data-rating="${Rating.Hard}">有点难</button><button class="primary" data-rating="${Rating.Good}">记得</button><button class="secondary" data-rating="${Rating.Easy}">很熟悉</button></div>`:`<p class="muted">回想意思或发音，先在心里读一遍。</p><button class="primary" data-action="reveal">显示答案</button>`}<div class="control-row" style="justify-content:center"><button class="text-button" data-speak="${escape(c.front)}">听韩语朗读</button></div></article><div class="resources">FSRS 按你的回答安排复习间隔。<button class="text-button" data-action="anki">导出复习卡到 Anki →</button></div>`;}
function renderLibrary(){const entries=librarySongs(state);return `<div class="welcome"><div><div class="eyebrow">MY SONGS · 每首歌都有自己的进度</div><h1>把喜欢的歌，一首首学会。</h1><p>共 ${entries.length} 首歌。切换歌曲会保留各自的歌词、笔记与学习进度。</p></div><button class="primary" data-action="newSong">＋ 添加歌曲</button></div><div class="library-toolbar"><label class="field-label">查找歌曲<input type="search" id="songSearch" placeholder="搜索歌名或歌手" value="${escape(libraryQuery)}"></label><label class="field-label">学习状态<select id="songFilter">${[['all','全部歌曲'],['new','未开始'],['learning','学习中'],['done','已学完']].map(([value,label])=>`<option value="${value}" ${libraryFilter===value?'selected':''}>${label}</option>`).join('')}</select></label></div><div class="song-library">${entries.map(entry=>{const total=entry.song.lines.length,count=entry.learned.length,status=total&&count>=total?'done':count?'learning':'new';return `<article class="panel song-entry" data-song-search="${escape((entry.song.title+' '+entry.song.artist).toLocaleLowerCase())}" data-song-status="${status}"><div class="section-head"><span class="eyebrow">${entry.id===state.songId?'当前练习':'歌曲库'}</span><span class="pill">${status==='done'?'已学完':status==='learning'?'学习中':total?'未开始':'待导入歌词'}</span></div><h2>${escape(entry.song.title)}</h2><p class="muted">${escape(entry.song.artist||'未填写歌手')}</p><div class="small-progress"><i style="width:${total?Math.round(count/total*100):0}%"></i></div><p class="helper">已学 ${count} / ${total} 句 · ${Object.keys(entry.notes).length} 条笔记</p><div class="control-row"><button class="primary" data-song-use="${escape(entry.id)}">${entry.id===state.songId?'继续练习':'切换到这首歌'}</button><button class="text-button" data-song-edit="${escape(entry.id)}">编辑信息</button></div><div class="control-row"><button class="text-button" data-song-lyrics="${escape(entry.id)}">${total?'替换歌词':'导入歌词'}</button><button class="text-button" data-song-delete="${escape(entry.id)}">删除</button></div></article>`;}).join('')}</div><section class="panel empty" id="libraryNoMatch" ${entries.length?'hidden':''}><h2>${entries.length?'没有匹配的歌曲':'从第一首歌开始。'}</h2><p class="muted">${entries.length?'试试其他歌名、歌手或学习状态。':'添加歌词后，学习记录会自动按歌曲保存。'}</p><button class="primary" data-action="newSong">添加歌曲</button></section><p class="helper">每日新句额度由所有歌曲共用，切歌不会增加当天的新句量。歌曲库与进度参与云同步；本地音频切歌后需重新选择。</p>`;}
function filterLibrary(){if(!el('songSearch'))return;libraryQuery=el('songSearch').value;libraryFilter=el('songFilter').value;let visible=0;document.querySelectorAll('[data-song-search]').forEach(card=>{card.hidden=!card.dataset.songSearch.includes(libraryQuery.trim().toLocaleLowerCase())||libraryFilter!=='all'&&card.dataset.songStatus!==libraryFilter;if(!card.hidden)visible++;});el('libraryNoMatch').hidden=visible>0;}
function renderHistory(){
 const all=studyHistory(state),days=historyDate?all.filter(d=>d.date===historyDate):all;
 const rating={1:'忘记了',2:'有点难',3:'记得',4:'很熟悉'};
 return `<div class="welcome"><div><div class="eyebrow">LEARNING HISTORY · 每一步都留下来</div><h1>回头看看，已经学了这么多。</h1><p>按北京时间记录知识点、课程、歌曲和复习。未打卡的学习也会保留。</p></div><button class="pill" data-action="export">导出完整备份</button></div><div class="stats"><div class="stat"><div><strong>${all.length}</strong><small>天有学习记录</small></div></div><div class="stat"><div><strong>${all.filter(d=>d.complete).length}</strong><small>天完成任务</small></div></div><div class="stat"><div><strong>${all.reduce((n,d)=>n+(d.reviews||d.reviewDetails.length),0)}</strong><small>次复习</small></div></div></div><div class="section-head"><h2>学习足迹</h2><label class="history-filter">按日期查看 <input type="date" id="historyDate" value="${escape(historyDate)}" aria-label="筛选学习日期"></label></div>${days.length?days.slice(0,historyLimit).map(d=>`<article class="panel history-day"><div class="section-head"><h2>${d.date}</h2><span class="pill">${d.complete?d.mode==='light'?'轻量任务已完成':'当日任务已完成':'已学习 · 未打卡'}</span></div>${d.activities.length?d.activities.map(a=>`<div class="history-item"><small>${a.kind==='basic'?'知识点':a.kind==='lesson'?'课程完成':'歌曲'} · ${escape(a.title)}</small><p class="history-front">${escape(a.front)}</p><p class="muted history-back">${escape(a.back||'尚未填写笔记')}</p></div>`).join(''):d.basic||d.lightBasic||d.song?'<p class="muted">旧版记录保留了当天的学习标记，未保存逐条内容；不会根据任务分配猜测学习时间。</p>':''}${d.reviewDetails.length?`<details class="history-reviews"><summary>复习 ${d.reviews||d.reviewDetails.length} 次 · 展开内容和评分</summary>${d.reviewDetails.map(r=>`<div class="history-item"><small>${escape(new Date(r.at).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit'}))} · ${rating[r.rating]}</small><p class="history-front">${escape(r.front)}</p><p class="muted history-back">${escape(r.back)}</p></div>`).join('')}</details>`:d.reviews?`<p class="muted">复习 ${d.reviews} 次，旧记录已无逐条明细。</p>`:''}</article>`).join(''):'<section class="panel empty"><div class="hangul-preview">하루</div><h2>这里会留下你学习的每一小步。</h2><p class="muted">'+(historyDate?'这个日期还没有学习记录。':'完成一个知识点，历史就会自动出现，无需先打卡。旧设备的记录可在学习设置中恢复备份。')+'</p><button class="primary" data-action="today">去今日学习</button></section>'}${days.length>historyLimit?'<button class="secondary" data-action="moreHistory">查看更多记录</button>':''}<p class="helper">新记录保存当时的内容，换歌后仍可回看。复习保留最近 10,000 次明细，日汇总长期保留。</p>`;
}
function renderSettings(){return `<div class="welcome"><div><div class="eyebrow">MAKE IT YOURS</div><h1>让学习适合你的生活。</h1><p>先让每天容易开始，再慢慢增加。</p></div></div><section class="panel sync-panel"><div class="section-head"><h2>自动保存</h2><button class="secondary" data-action="syncNow">立即同步</button></div><p id="cloudStatus">${escape(cloud.status)}</p><p class="helper">同一账号在手机、电脑上自动同步。离线时先保存在当前设备，联网后重试。旧电脑的进度可通过下方备份恢复。</p><div id="conflictActions" ${cloud.conflict?'':'hidden'}><p>另一台设备也修改了进度。选择前会先下载本机备份，避免丢失。</p><div class="control-row"><button class="secondary" data-action="useCloud">使用云端版本</button><button class="secondary" data-action="keepLocal">用本机版本更新云端</button></div></div>${cloud.ready?'':'<a class="text-button" href="/signin-with-chatgpt?return_to=/" target="_top">重新连接现有登录 ↗</a>'}</section><div class="columns"><section class="panel"><h2>我的日常节奏</h2><label class="field-label">每天的新歌词<select id="quota">${[1,2].map(n=>`<option value="${n}" ${state.quota===n?'selected':''}>${n} 句</option>`).join('')}</select></label><label class="field-label">每天的学习时间<select id="minutes">${[3,15,20].map(n=>`<option value="${n}" ${state.minutes===n?'selected':''}>${n} 分钟${n===3?' · 轻量模式':''}</option>`).join('')}</select></label><p class="helper">句数调整从下一天生效；今天已分配的句子会保留。每天按北京时间划分。</p><button class="primary" id="saveSettings">保存节奏</button></section><section class="panel"><h2>备份与开源</h2><p class="muted" style="font-size:12px">在线登录后自动云同步；导出备份也能保留一份独立副本。本地页面的旧记录需在此恢复一次。</p><div class="control-row"><button class="secondary" data-action="export">导出备份</button><label class="secondary" style="cursor:pointer">恢复备份<input type="file" id="restoreFile" accept="application/json,.json" hidden></label></div><div class="control-row"><button class="secondary" data-action="anki">导出 Anki 卡片</button>${state.song.lines.some(x=>x.start!==null)?'<button class="text-button" data-action="srt">导出 SRT</button>':''}</div><p class="helper">Anki 导出为 TSV 文本卡片；没有连接 Anki 的实时同步。</p><p class="helper">复用 asbplayer 的字幕时间轴与 SRT 导出，复习采用 ts-fsrs。</p><a class="text-button" href="source.zip" download>下载本版本完整源码（AGPL-3.0） ↓</a><p class="helper"><a href="THIRD_PARTY_NOTICES.md" target="_blank">开源来源与许可证</a></p></section></div>`;}
function bind(){bindNotebook(document);bindKnowledge(document);bindCards(document);document.querySelectorAll('[data-mistake]').forEach(button=>button.onclick=()=>openMistakePractice([button.dataset.mistake]));if(el('mistakesAll'))el('mistakesAll').onchange=event=>{mistakesAll=event.target.checked;render();};if(el('songSearch')){el('songSearch').oninput=filterLibrary;el('songFilter').onchange=filterLibrary;filterLibrary();}document.querySelectorAll('[data-song-use]').forEach(b=>b.onclick=()=>useSong(b.dataset.songUse));document.querySelectorAll('[data-song-edit]').forEach(b=>b.onclick=()=>editSong(b.dataset.songEdit));document.querySelectorAll('[data-song-delete]').forEach(b=>b.onclick=()=>deleteSong(b.dataset.songDelete));document.querySelectorAll('[data-song-lyrics]').forEach(b=>b.onclick=()=>{useSong(b.dataset.songLyrics);openImport();});if(el('historyDate'))el('historyDate').onchange=e=>{historyDate=e.target.value;render();};document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>openLesson(Number(b.dataset.lesson)));document.querySelectorAll('[data-speak]').forEach(b=>b.onclick=()=>speak(b.dataset.speak));document.querySelectorAll('[data-rating]').forEach(b=>b.onclick=()=>{lastRating=rateCard(state,reviewId,Number(b.dataset.rating)).undo;reviewId=null;revealed=false;save();render();});document.querySelectorAll('[data-note]').forEach(t=>t.oninput=()=>{state.notes[t.dataset.note]=t.value;const card=state.cards[songCardId(state,t.dataset.note)];if(card)card.back=t.value||'回想意思，读一遍，再跟着原唱唱一遍。';save();});document.querySelectorAll('[data-learn]').forEach(b=>b.onclick=()=>{const line=state.song.lines.find(x=>x.id===b.dataset.learn);try{learnLine(state,line);save();updateSongLearning();toast('这句存进记忆了，复习时会再见。');}catch(error){toast(error.message);}});document.querySelectorAll('[data-segment]').forEach(b=>b.onclick=()=>{const line=state.song.lines.find(x=>x.id===b.dataset.segment);selectSegment([line]);playSegment();});if(el('saveSettings'))el('saveSettings').onclick=()=>{state.quota=Number(el('quota').value);state.minutes=Number(el('minutes').value);mini=state.minutes===3;save();toast('已保存。从小步开始。');navigate('today');};if(el('restoreFile'))el('restoreFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>3000000)throw Error('备份文件过大。');const restored=normalizeState(JSON.parse(await file.text()));showDialog('恢复进度',`<h2>用备份恢复学习进度</h2><p>备份含 ${restored.completedLessons.length} 节小课、${librarySongs(restored).length} 首歌和 ${Object.keys(restored.cards).length} 张卡片。当前进度会替换。</p><button class="primary" id="confirmRestore">先备份当前进度，再恢复</button>`);el('confirmRestore').onclick=()=>{exportState();resetSongPlayer();state=restored;storageWarning='';mini=state.minutes===3;rebuildTimeline();save();el('lessonDialog').close();navigate('today');toast('备份已恢复。');};}catch(err){toast(err.message);}};}
function action(a){if(a==='review')reviewMode='due';if(views.includes(a))navigate(a);else if(a==='mistakes'){reviewMode='mistakes';render();}else if(a==='practiceMistakes'){openMistakePractice(mistakeList(state).map(x=>x.id));}else if(a==='undoRating'){const change=lastRating;lastRating=null;if(undoRating(state,change)){reviewMode='due';reviewId=change.id;revealed=true;save();render();toast('上次评分已撤销，请重新选择记忆程度。');}else{render();toast('进度已变化，这次评分无法再撤销。');}}else if(a==='allCards'){reviewMode='all';cardLimit=60;render();}else if(a==='dueCards'){reviewMode='due';reviewId=null;revealed=false;render();}else if(a==='moreCards'){cardLimit+=60;refreshCards();}else if(a==='dailyLesson'){const id=today().lessonId;openLesson(id===-1?lessons.length-1:id,mini);}else if(a==='dailyPractice'){openPractice();}else if(a==='warmup'){openWarmup();}else if(a==='nextLesson'){const id=lessons.findIndex((_,i)=>!state.completedLessons.includes(i));if(id<0)navigate('course');else openLesson(id);}else if(a==='mini'){mini=!mini;render();}else if(a==='completeDay')dailyComplete();else if(a==='import')openImport();else if(a==='newSong')openImport('add');else if(a==='reveal'){revealed=true;render();}else if(a==='anki'){download('haru-anki.tsv',toAnki(state));toast('Anki 中选择导入，字段对应 Front、Back、Tags。');}else if(a==='export')exportState();else if(a==='syncNow'){cloud.sync();}else if(a==='keepLocal'){exportState();cloud.resolve(true).then(render);}else if(a==='useCloud'){exportState();cloud.resolve(false).then(render);}else if(a==='moreHistory'){historyLimit+=60;render();}else if(a==='srt')download('haru-subtitles.srt',toSrt(state.song.lines));}
function exportState(){download('haru-progress-'+dayKey()+'.json',JSON.stringify(state,null,2),'application/json');}
function showDialog(meta,body){el('lessonMeta').textContent=meta;el('lessonBody').innerHTML=body;if(!el('lessonDialog').open)el('lessonDialog').showModal();}
function openPractice(){const d=today(),id=d.lessonId<0?lessons.length-1:d.lessonId;session={id,index:0,quiz:d.drillProgress||0,phase:'quiz',light:false,practiceOnly:true,questions:lessonQuestions(lessons[id])};showLesson();}
function openWarmup(){
 const id=today().lessonId<0?lessons.length-1:today().lessonId,items=warmupItems(lessons[id],id),light=mini;let index=today().warmupProgress||0;
 const show=()=>{const x=items[index];showDialog(`跟读热身 · ${index+1} / ${items.length}`,`<h2>听一遍，跟读三遍，再独立读一次。</h2><p class="lyric-text">${escape(x.front)}</p><p>${escape(x.back)}</p><p class="lesson-desc">${escape(x.note)}</p><button class="secondary" id="warmupSpeak">▶ 听韩语示范</button><p class="helper">示范使用设备的韩语语音；无语音时也可以按文字做口型与回忆练习。这是基础热身，不是原唱。</p><div class="lesson-navigation"><span class="helper">练完后再继续</span><button class="primary" id="warmupNext">${light?'完成今天这一组':index===items.length-1?'完成热身':'练好了，下一组'} →</button></div>`);
 el('warmupSpeak').onclick=()=>speak(x.audio);el('warmupNext').onclick=()=>{recordStudy(state,{kind:'basic',id:`warmup:${id}:${index}`,title:'跟读热身 · '+lessons[id].title,front:x.front,back:x.back+'\n'+x.note});index++;if(index===items.length){today().warmup=true;delete today().warmupProgress;}else today().warmupProgress=index;if(light)today().lightWarmup=true;save();if(light||index===items.length){el('lessonDialog').close();render();toast(light?'今天的一组跟读已记录，下次接着练。':'4 组跟读热身已记录。可以听 MV，或继续下一课。');}else show();};};show();
}
function selectSegment(lines){const segment=practiceSegment(lines);if(!segment)return;el('startTime').value=segment.start;el('endTime').value=segment.end;}
function openLesson(id,light=false){session=lessonSession(state,id,light);showLesson();}
function showLesson(){const l=lessons[session.id];if(session.phase==='learn'){const x=l.items[session.index];showDialog(`LESSON ${String(session.id+1).padStart(2,'0')} · ${l.title}`,`<h2>${l.title}</h2><div class="lesson-char">${escape(x.front)}</div><p style="text-align:center">${escape(x.back)}</p><p class="lesson-desc">${x.note}</p><button class="secondary" id="lessonSpeak">▶ 听韩语示范</button><p class="helper">使用浏览器韩语语音；如设备没有韩语语音，可到基础词典听真人发音。</p><div class="lesson-navigation"><button class="text-button" id="lessonPrev" ${session.index===0?'disabled':''}>← 上一个</button><span class="helper">${session.index+1} / ${l.items.length}</span><button class="primary" id="lessonNext">${session.light?'完成这一步':session.index===l.items.length-1?'做 8 道练习':'继续'} →</button></div>`);el('lessonSpeak').onclick=()=>speak(x.audio);el('lessonPrev').onclick=()=>{session.index--;showLesson();};el('lessonNext').onclick=()=>{learnLessonItem(state,session.id,session.index);if(session.light){if(today().lessonId===session.id)today().lightBasic=true;save();el('lessonDialog').close();render();toast('今天的小知识点学完了。下次继续。');}else if(session.index<l.items.length-1){session.index++;save();showLesson();}else{session.phase='quiz';save();showLesson();}};}else{const q=session.questions[session.quiz];showDialog(`${session.mistakeKeys?'错题巩固':'小练习'} · ${session.quiz+1} / ${session.questions.length}`,`<h2>${escape(q[0])}</h2><p class="helper">先想一下，再选择。答错会解释，再试一次。</p>${q[4]?`<button class="secondary" id="quizSpeak">▶ 听示范</button><details class="listening-hint"><summary>听不到？查看文字提示</summary><p>${escape(q[5])}</p></details>`:''}${q[1].map((x,i)=>`<button class="choice" data-choice="${i}">${escape(x)}</button>`).join('')}<div id="quizFeedback" role="status"></div><div class="lesson-navigation"><span class="helper">答对后自动记入历史。</span><button class="primary" id="quizNext" disabled>${session.quiz===session.questions.length-1?session.mistakeKeys?'完成本轮巩固':'完成小课':'下一题'} →</button></div>`);if(el('quizSpeak'))el('quizSpeak').onclick=()=>speak(q[4]);document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{const correct=recordQuizAnswer(state,session,Number(b.dataset.choice));save();b.disabled=true;if(el('mistakeCount'))el('mistakeCount').textContent=mistakeList(state).length;b.classList.add(correct?'correct':'wrong');el('quizFeedback').innerHTML=`<div class="feedback ${correct?'good':'bad'}">${correct?'答对了。':'再想想，已加入错题本。'} ${escape(q[3])}</div>`;if(correct){el('quizNext').disabled=false;document.querySelectorAll('[data-choice]').forEach(x=>x.disabled=true);}});el('quizNext').onclick=()=>{if(session.quiz<session.questions.length-1){session.quiz++;if(!session.mistakeKeys){if(session.practiceOnly)today().drillProgress=session.quiz;else state.quizProgress[session.id]=session.quiz;}save();showLesson();}else{if(session.mistakeKeys){el('lessonDialog').close();toast('本轮错题巩固完成，已保存学习历史。');return;}if(session.practiceOnly){today().drill=true;delete today().drillProgress;recordStudy(state,{kind:'basic',id:'drill:'+session.id,title:'今日巩固 · '+l.title,front:'8 道识读与听辨练习',back:'已完成全部练习'});save();el('lessonDialog').close();render();toast('今日巩固完成，可以继续下一课或跟读热身。');return;}if(!state.completedLessons.includes(session.id))state.completedLessons.push(session.id);delete state.lessonProgress[session.id];delete state.quizProgress[session.id];recordStudy(state,{kind:'lesson',id:'lesson:'+session.id,title:l.title,front:l.title,back:'完成知识点与 8 道识读、听辨练习'});if(today().lessonId===session.id){today().basic=true;today().drill=true;}save();render();const next=lessons.findIndex((_,i)=>!state.completedLessons.includes(i));showDialog('小课完成',`<h2>${l.title}，完成了 ✓</h2><p>已完成 8 道练习，知识点已加入复习。还想多学一点，可以直接继续。</p><div class="control-row"><button class="primary" id="afterLesson">${next<0?'回顾全部课程':'继续下一课：'+escape(lessons[next].title)}</button><button class="secondary" id="afterWarmup">做跟读热身</button><button class="text-button" id="afterClose">稍后继续</button></div>`);el('afterLesson').onclick=()=>{el('lessonDialog').close();action('nextLesson');};el('afterWarmup').onclick=openWarmup;el('afterClose').onclick=()=>el('lessonDialog').close();}};}}
function speak(text){if(!('speechSynthesis' in window)){toast('当前浏览器没有朗读功能。请使用原唱或基础词典音频。');return;}const voices=speechSynthesis.getVoices();const voice=voices.find(x=>/^ko(?:-|_)/i.test(x.lang));if(!voice){toast('设备没有可用韩语语音。请使用原唱，或到基础词典听发音。');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='ko-KR';u.voice=voice;u.rate=.75;speechSynthesis.speak(u);}
function songFields(song){return `<label class="field-label">歌曲名称<input id="songTitle" value="${escape(song.title)}" maxlength="100"></label><label class="field-label">歌手<input id="songArtist" value="${escape(song.artist)}" maxlength="100"></label><label class="field-label">YouTube 地址或 ID（可选）<input id="songVideo" value="${escape(song.videoId)}" placeholder="https://www.youtube.com/watch?v=..."></label><label class="field-label">Bilibili 地址或 BV 号（可选）<input id="songBili" value="${escape(song.biliBvid)}" placeholder="https://www.bilibili.com/video/BV..."></label><p class="helper">也可以只导入歌词，使用本地音频练习。</p>`;}
function readSongFields(source='bilibili'){
 const raw=el('songVideo').value.trim(),videoId=raw.match(/(?:v=|youtu\.be\/|embed\/)([A-Za-z0-9_-]{11})/)?.[1]||raw;
 if(videoId&&!/^[A-Za-z0-9_-]{11}$/.test(videoId))throw Error('请填写有效的 YouTube 地址或 11 位 ID，或留空。');
 const bili=el('songBili').value.trim(),biliBvid=bili.match(/BV[0-9A-Za-z]{10}/)?.[0]||'';
 if(bili&&!biliBvid)throw Error('请填写有效的 Bilibili BV 号或地址，或留空。');
 return {title:el('songTitle').value.trim()||'我的歌曲',artist:el('songArtist').value.trim(),videoId,biliBvid,mvSource:source==='youtube'&&videoId?'youtube':biliBvid?'bilibili':videoId?'youtube':source};
}
function resetSongPlayer(){audio.pause();disposeVideo();segmentActive=false;loopOn=false;if(localUrl)URL.revokeObjectURL(localUrl);localUrl=null;audio.removeAttribute('src');audio.load();}
function useSong(id){if(id!==state.songId){resetSongPlayer();switchSong(state,id);rebuildTimeline();save();}navigate('song');}
function editSong(id){const entry=librarySongs(state).find(x=>x.id===id);if(!entry)return;showDialog('编辑歌曲信息',`<h2>编辑歌曲信息</h2>${songFields(entry.song)}<div id="songEditError" role="status"></div><button class="primary" id="saveSongDetails">保存信息</button>`);el('saveSongDetails').onclick=()=>{try{Object.assign(entry.song,readSongFields(entry.song.mvSource));save();el('lessonDialog').close();render();toast('歌曲信息已保存，歌词和进度保持不变。');}catch(error){el('songEditError').textContent=error.message;}};}
function deleteSong(id){const entry=librarySongs(state).find(x=>x.id===id);if(!entry)return;showDialog('删除歌曲',`<h2>删除《${escape(entry.song.title)}》？</h2><p>将移出歌曲库并删除这首歌的歌词、笔记和学习进度。已经产生的学习历史和复习卡会保留。</p><p class="helper">确认后先下载完整备份，再删除。</p><button class="secondary" id="cancelDeleteSong">取消</button> <button class="primary" id="confirmDeleteSong">备份并删除这首歌</button>`);el('cancelDeleteSong').onclick=()=>el('lessonDialog').close();el('confirmDeleteSong').onclick=()=>{exportState();if(id===state.songId)resetSongPlayer();removeSong(state,id);rebuildTimeline();save();el('lessonDialog').close();navigate('library');toast('歌曲已移出歌曲库，历史和复习卡已保留。');};}
function openImport(mode=state.songId?'replace':'add'){
 importPreview=null;const adding=mode==='add',song=adding?{title:'',artist:'',videoId:'',biliBvid:''}:state.song;
 showDialog(adding?'添加到歌曲库':'替换当前歌曲歌词',`<h2>${adding?'加入下一首喜欢的歌。':'导入 / 替换这首歌的歌词。'}</h2><p class="helper">${adding?'已有歌曲和学习进度会保留。':'替换会重建这首歌的进度，旧历史和卡片保留。'}登录后歌曲库随账号同步，音频仍在本机选择。</p>${songFields(song)}<label class="field-label">歌词<textarea class="notes" id="lyricsText" style="min-height:150px" placeholder="每行放一句韩文歌词；也支持 LRC / SRT。"></textarea></label><label class="secondary" style="display:inline-block;cursor:pointer;margin-top:10px">选择歌词文件<input id="lyricsFile" type="file" accept=".txt,.lrc,.srt,text/plain" hidden></label><div id="importMessage" role="status"></div><div class="control-row"><button class="primary" id="previewImport">检查并预览</button></div>`);
 const invalidate=()=>{importPreview=null;el('importMessage').innerHTML='';};
 for(const id of ['songTitle','songArtist','songVideo','songBili','lyricsText'])el(id).oninput=invalidate;
 el('lyricsFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>300000){toast('请导入 300 KB 以内的歌词文件。');return;}el('lyricsText').value=await f.text();invalidate();};
 el('previewImport').onclick=()=>{try{
  importPreview={...readSongFields(adding?'bilibili':state.song.mvSource),lines:parseLyrics(el('lyricsText').value)};
  el('importMessage').innerHTML=`<div class="feedback good">找到 ${importPreview.lines.length} 句韩语。所有歌曲共用每天 ${state.quota} 句的新句额度。</div><p class="helper">${adding?'添加后可在歌曲库随时切换，不会覆盖其他歌曲。':state.song.lines.length?'确认后先下载旧备份，再替换这首歌的歌词。':'确认后从第一句开始。'}</p><button class="primary" id="confirmImport">${adding?'添加并开始练习':'确认导入'}</button>`;
  el('confirmImport').onclick=()=>{
   resetSongPlayer();
   if(adding)addSong(state,importPreview);
   else{if(state.song.lines.length)exportState();const key=dayKey();state.days[key]??={};state.days[key].songLearnedCount=dailySongCount(state);state.song=importPreview;state.learned=[];state.notes={};state.songBatches={};state.segment={start:0,end:10,rate:0.8};}
   rebuildTimeline();save();el('lessonDialog').close();navigate('song');toast(adding?'已加入歌曲库，原来的歌还在。':'歌词已导入。');
  };
 }catch(error){el('importMessage').innerHTML=`<div class="feedback bad">${escape(error.message)}</div>`;}};
}
function disposeVideo(){pendingSegment=false;segmentActive=false;const frame=el('videoWrap')?.querySelector('iframe');if(frame&&!player)frame.remove();if(player){try{player.destroy();}catch{}player=null;}playerReady=false;clearInterval(ticker);ticker=null;}
function mountSong(){
 el('audioHost').append(audio);audio.playbackRate=state.segment.rate;
 const source=videoSource(state.song);if(source)state.song.mvSource=source;
 el('mvSource').value=state.song.mvSource;el('loadVideo').onclick=()=>loadVideo();
 el('mvSource').onchange=()=>{state.song.mvSource=el('mvSource').value;save();loadVideo();el('openMv').hidden=state.song.mvSource==='youtube'?!state.song.videoId:!state.song.biliBvid;el('openMv').href=state.song.mvSource==='youtube'?'https://www.youtube.com/watch?v='+state.song.videoId:'https://www.bilibili.com/video/'+state.song.biliBvid+'/';};
 el('audioFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;segmentActive=false;audio.pause();if(localUrl)URL.revokeObjectURL(localUrl);localUrl=URL.createObjectURL(f);audio.src=localUrl;el('audioName').textContent=f.name+' · 本地播放';disposeVideo();startTicker();toast('音频已准备好，点击歌词即可播放对应片段。');};
 if(el('playDaily'))el('playDaily').onclick=()=>{selectSegment(songBatch(state));playSegment();};
 el('playSegment').onclick=playSegment;el('stopPlayback').onclick=()=>{audio.pause();if(playerReady)player.pauseVideo();};
 el('setStart').onclick=()=>{el('startTime').value=currentTime().toFixed(1);};el('setEnd').onclick=()=>{el('endTime').value=currentTime().toFixed(1);};
 el('loopToggle').onclick=()=>{if(!localUrl&&state.song.mvSource==='bilibili'){toast('当前视频支持跳转；循环可使用 YouTube 或本地音频。');return;}loopOn=!loopOn;el('loopToggle').textContent='循环：'+(loopOn?'开启':'关闭');el('loopToggle').setAttribute('aria-pressed',String(loopOn));};
 el('rate').onchange=()=>{state.segment.rate=Number(el('rate').value);audio.playbackRate=state.segment.rate;if(playerReady){const available=player.getAvailablePlaybackRates();const closest=available.reduce((best,x)=>Math.abs(x-state.segment.rate)<Math.abs(best-state.segment.rate)?x:best,1);player.setPlaybackRate(closest);el('playerStatus').textContent=`MV 实际播放速度：${closest}×（按播放器可用速度选择）`;}save();};
 startTicker();if(!localUrl&&source)loadVideo();
}
function currentTime(){return localUrl?audio.currentTime:playerReady?player.getCurrentTime():0;}
function duration(){return localUrl?audio.duration:playerReady?player.getDuration():Infinity;}
async function playSegment(){
 const start=Number(el('startTime').value),end=Number(el('endTime').value);
 if(localUrl&&!Number.isFinite(audio.duration)){toast('音频还在加载，请稍后再试。');return;}
 if(!validateSegment(start,end,duration())){toast('请设置有效片段：A ≥ 0，B > A，且不超过音频长度。');return;}
 if(!localUrl&&!videoSource(state.song)){toast('这首歌还没有视频链接，可以先做发音热身。');return;}
 state.segment={...state.segment,start,end};save();
 if(!localUrl&&state.song.mvSource==='bilibili'){loadVideo(start);toast('已跳转到这句的起点。Bilibili 需要在播放器内控制暂停。');return;}
 if(!localUrl&&!playerReady){loadVideo();pendingSegment=true;el('playerStatus').textContent='正在准备今日片段，视频就绪后播放。';return;}
 segmentActive=true;
 if(localUrl){audio.currentTime=start;audio.playbackRate=state.segment.rate;try{await audio.play();}catch{segmentActive=false;toast('音频无法播放，请换一个浏览器支持的格式。');}}
 else{player.seekTo(start,true);const rates=player.getAvailablePlaybackRates();const closest=rates.reduce((best,x)=>Math.abs(x-state.segment.rate)<Math.abs(best-state.segment.rate)?x:best,1);player.setPlaybackRate(closest);player.playVideo();el('playerStatus').textContent=`MV 实际播放速度：${closest}×`;}
}
function startTicker(){clearInterval(ticker);ticker=setInterval(()=>{if(view!=='song')return;const t=currentTime(),playing=localUrl?!audio.paused:playerReady&&player.getPlayerState()===1;if(playing&&segmentActive&&t>=state.segment.end){if(loopOn){if(localUrl)audio.currentTime=state.segment.start;else player.seekTo(state.segment.start,true);}else{segmentActive=false;audio.pause();if(playerReady)player.pauseVideo();}}const showing=collection.subtitlesAt(Math.floor(t*1000)).showing;if(showing.length&&el('liveSubtitle'))el('liveSubtitle').textContent=showing.map(x=>x.text).join(' / ');},80);}
function loadVideo(start=null){
 if(state.song.mvSource==='youtube'?!state.song.videoId:!state.song.biliBvid){disposeVideo();el('videoWrap').innerHTML='<div class="video-placeholder"><strong>当前来源没有视频链接</strong><p>可在歌曲库编辑信息，或直接做发音热身。</p></div>';return;}
 audio.pause();segmentActive=false;disposeVideo();playerFailed=false;
 if(state.song.mvSource!=='youtube'){
  const params=new URLSearchParams({bvid:state.song.biliBvid,p:'1',autoplay:start===null?'0':'1',danmaku:'0'});if(start!==null)params.set('t',String(start));
  el('videoWrap').innerHTML='<iframe title="Bilibili MV 播放器" src="https://player.bilibili.com/player.html?'+params.toString()+'" allow="autoplay; fullscreen; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>';
  el('playerStatus').textContent=start===null?'MV 已准备好，点击播放器即可观看。歌词有时间轴时可直接跳转到对应句。':'已跳转到 '+start.toFixed(1)+' 秒。Bilibili 的暂停和速度请在播放器内控制；精确停止与循环支持 YouTube 或本地音频。';return;
 }
 el('videoWrap').innerHTML='<div id="youtubePlayer"></div>';startTicker();
 const create=()=>{if(view!=='song'||!el('youtubePlayer')||player)return;player=new YT.Player('youtubePlayer',{videoId:state.song.videoId,playerVars:{playsinline:1,origin:location.origin},events:{onReady:()=>{playerReady=true;el('playerStatus').textContent='MV 已就绪。今日片段会按歌词时间轴自动选取。';if(pendingSegment){pendingSegment=false;playSegment();}},onError:()=>{playerFailed=true;pendingSegment=false;el('playerStatus').textContent='当前视频无法内嵌播放，可打开原视频或先做跟读热身。';toast('视频暂时无法播放，可以先做跟读热身。');}}});};
 if(window.YT?.Player)create();else{window.onYouTubeIframeAPIReady=create;if(!document.querySelector('script[data-youtube]')){const script=document.createElement('script');script.src='https://www.youtube.com/iframe_api';script.dataset.youtube='1';script.onerror=()=>{script.remove();pendingSegment=false;if(el('playerStatus'))el('playerStatus').textContent='无法加载 YouTube。可以打开原视频，或先做跟读热身。';};document.head.append(script);}}
}
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>navigate(b.dataset.view));el('closeLesson').onclick=()=>el('lessonDialog').close();el('lessonDialog').addEventListener('close',()=>{window.speechSynthesis?.cancel();if(view==='review'&&reviewMode==='mistakes')render();});el('exportBtn').onclick=exportState;el('syncIndicator').onclick=()=>navigate('settings');document.querySelector('.brand').onclick=e=>{e.preventDefault();navigate('today');};window.addEventListener('beforeunload',save);
window.addEventListener('popstate',()=>{const next=viewFromUrl();if(next!==view)navigate(next);});
window.addEventListener('hashchange',()=>{const next=viewFromUrl();if(next!==view)navigate(next);});
async function start(){try{const remote=await cloud.connect();if(remote){state=remote;mini=state.minutes===3;storageWarning='';rebuildTimeline();}render();if(cloud.dirty)cloud.sync();}catch{el('content').innerHTML='<section class="panel"><h1>暂时无法连接学习进度</h1><p>为保护已有记录，尚未开始新的学习。请检查网络后刷新重试。</p><button class="primary" id="retryConnection">重新连接</button></section>';el('retryConnection').onclick=()=>location.reload();}}
window.addEventListener('online',()=>cloud.sync());
window.addEventListener('pagehide',()=>{if(cloud.dirty)cloud.sync();});
window.addEventListener('focus',()=>{if(!el('lessonDialog').open)cloud.sync();});
setInterval(()=>{if(document.visibilityState==='visible'&&!el('lessonDialog').open)cloud.sync();},30000);
start();
